<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Переодевашка — вход</title><link rel="manifest" href="manifest.webmanifest"><link rel="apple-touch-icon" href="apple-touch-icon.png"><link rel="icon" type="image/png" href="icon-192.png"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Переодевашка"><meta name="theme-color" content="#2f1a28"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=Unbounded:wght@500;600;700;800&family=Manrope:wght@400;500;600;700&display=swap&subset=cyrillic"><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;min-height:100dvh;display:grid;grid-template-columns:1.1fr 1fr;font:15px/1.6 "Manrope",-apple-system,"Segoe UI",sans-serif;color:#2b2129;background:#faf7f3;-webkit-font-smoothing:antialiased}.side{position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between;padding:48px 56px;color:#f4e4d0;background:radial-gradient(ellipse at 80% 10%,#7d3a6766,transparent 60%),linear-gradient(160deg,#3a2232,#55203f 60%,#2f1a28)}.side::after{content:'';position:absolute;right:-120px;bottom:-120px;width:420px;height:420px;border-radius:50%;border:1px solid #e9c99a33;box-shadow:0 0 0 60px #e9c99a0d,0 0 0 120px #e9c99a08}.brand{display:flex;align-items:center;gap:12px;font:700 18px "Unbounded","Manrope",sans-serif;letter-spacing:-.04em;color:#fff}.mark{width:42px;height:42px;border-radius:13px;display:grid;place-items:center;background:#ffffff1a;font:700 20px "Unbounded","Manrope",sans-serif;color:#fff}.side h2{font:700 clamp(28px,3.4vw,46px)/1.1 "Unbounded","Manrope",sans-serif;letter-spacing:-.045em;margin:0;color:#fff;max-width:520px}.side h2 em{color:#e9c99a;font-style:normal}.side p{margin:18px 0 0;max-width:420px;color:#d9bfae;font-size:15px}.eyebrow{display:block;margin-bottom:18px;font-size:11px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:#e9c99a}.side small{font-size:12px;color:#b89a8c}main{display:flex;align-items:center;justify-content:center;padding:40px 24px}form,.box{width:100%;max-width:380px}h1{font:700 30px/1.1 "Unbounded","Manrope",sans-serif;letter-spacing:-.045em;margin:0 0 10px}.lead{margin:0 0 30px;color:#8b7f87;font-size:14px}label{display:grid;gap:8px;margin:0 0 18px;font-size:13px;font-weight:700;color:#5d5159}input,button{font:inherit;min-width:0;min-height:52px;border-radius:12px}input{width:100%;padding:13px 15px;border:1px solid #ddd1c9;background:#fff;color:#2b2129;font-size:16px;transition:border-color .15s,box-shadow .15s}input:focus{outline:none;border-color:#6d2e58;box-shadow:0 0 0 4px #6d2e581a}button{width:100%;margin-top:8px;border:0;background:#6d2e58;color:#fff;font-size:15px;font-weight:700;cursor:pointer;box-shadow:0 2px 4px #55203f26,0 14px 30px #6d2e5833;transition:background .15s}button:hover:not(:disabled){background:#55203f}button:disabled{opacity:.45;cursor:not-allowed}#message{min-height:22px;margin:16px 0 0;color:#8a5a4f;font-size:13px}.note{margin-top:28px;padding-top:20px;border-top:1px solid #ebe3dc;color:#8b7f87;font-size:12.5px;line-height:1.7}button{background:linear-gradient(135deg,#7f3a69,#5a2244);box-shadow:0 1px 0 #ffffff2e inset,0 2px 4px #55203f26,0 16px 32px -12px #6d2e5880;transition:transform .25s cubic-bezier(.22,.8,.24,1),box-shadow .25s,background .25s}button:hover:not(:disabled){background:linear-gradient(135deg,#8a416f,#5f2648);transform:translateY(-1px)}input{border-radius:14px;border-color:#e6d9dd}main{background:radial-gradient(700px 360px at 80% -80px,#f7e3ea,#faf7f300 70%),#faf7f3}button{border-radius:999px}@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}.box,.side>div{animation:rise .6s cubic-bezier(.22,.8,.24,1) both}@media(prefers-reduced-motion:reduce){.box,.side>div{animation:none}}@media(max-width:860px){body{grid-template-columns:1fr}.side{padding:28px 24px 34px;gap:36px}.side h2{font-size:28px}.side::after{display:none}.side small{display:none}main{padding:36px 22px 48px;align-items:flex-start}}#key{font:700 24px/1 "Unbounded","Manrope",sans-serif;letter-spacing:.14em;text-align:center;text-transform:uppercase;min-height:64px}.tgbtn{display:flex;align-items:center;justify-content:center;gap:10px;min-height:52px;margin-top:12px;border-radius:999px;border:1px solid #e6d8dc;background:#fff;color:#6d2e58;font-weight:700;text-decoration:none;transition:transform .25s cubic-bezier(.22,.8,.24,1),box-shadow .25s}.tgbtn:hover{transform:translateY(-1px);box-shadow:0 12px 24px -14px #55203f55}.tgbtn[hidden]{display:none}details.owner{margin-top:26px;border-top:1px solid #ebe3dc;padding-top:16px}details.owner summary{cursor:pointer;color:#8b7f87;font-size:13px;font-weight:700;list-style:none}details.owner summary::-webkit-details-marker{display:none}details.owner[open] summary{margin-bottom:16px}</style><aside class="side"><div class="brand"><span class="mark">m</span>memorybox</div><div><span class="eyebrow">Закрытая студия</span><h2>Куклы‑липучки <em>по фото</em> для вашего бизнеса</h2><p>Кукла по фото ребёнка, гардероб без перерисовки вещей, готовые листы для печати и плоттерной резки.</p></div><small>Доступ только для участниц студии</small></aside><main><div class="box"><h1>Вход в студию</h1><p class="lead">Ключ входа выдаёт Telegram-бот студии.</p><form id="keyForm"><label>Ключ входа<input id="key" autocomplete="one-time-code" autocapitalize="characters" spellcheck="false" maxlength="9" placeholder="XXXX-XXXX" required></label><button id="keySubmit" disabled>Войти по ключу</button></form><a class="tgbtn" id="botLink" hidden target="_blank" rel="noopener">Получить ключ в Telegram</a><p id="message" role="status">Подключаюсь…</p><p class="note">Нет доступа? Откройте бота, выберите тариф и оплатите: после подтверждения ключ придёт в чат. Ключ действует 24 часа и работает один раз.</p><details class="owner"><summary>Вход владельца по паролю</summary><form id="form"><label>Логин<input id="login" autocomplete="username" maxlength="40"></label><label>Пароль<input id="password" type="password" autocomplete="current-password" maxlength="200"></label><button id="submit" disabled>Войти</button></form></details></div></main><script>
let csrf='';async function json(r){let j;try{j=await r.json()}catch{throw Error('Сервер не ответил. Проверь, что PHP включён.')}if(!r.ok){const e=Error(j.error||'Ошибка входа');e.expired=!!j.expired;throw e}return j}
const msg=t=>document.getElementById('message').textContent=t;
(async()=>{try{const j=await json(await fetch('api.php?action=session',{cache:'no-store'}));if(j.user){location.replace('index.php');return}csrf=j.csrf;document.getElementById('keySubmit').disabled=false;document.getElementById('submit').disabled=false;msg(j.expired?'Срок доступа закончился. Продлите его в Telegram-боте и получите новый ключ.':'');if(j.bot){const a=document.getElementById('botLink');a.href='https://t.me/'+j.bot;a.textContent='Открыть бота @'+j.bot;a.hidden=false}}catch(e){msg(e.message)}})();
const keyInput=document.getElementById('key');keyInput.oninput=()=>{let v=keyInput.value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8);keyInput.value=v.length>4?v.slice(0,4)+'-'+v.slice(4):v};
document.getElementById('keyForm').onsubmit=async e=>{e.preventDefault();const b=document.getElementById('keySubmit');b.disabled=true;msg('Проверяю ключ…');try{await json(await fetch('api.php?action=login.key',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({key:keyInput.value})}));location.replace('index.php')}catch(err){msg(err.message);b.disabled=false}};
document.getElementById('form').onsubmit=async e=>{e.preventDefault();const b=document.getElementById('submit');b.disabled=true;try{await json(await fetch('api.php?action=login',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({login:document.getElementById('login').value,password:document.getElementById('password').value})}));location.replace('index.php')}catch(err){msg(err.message);b.disabled=false}};
</script></html>